-- Applied initially to the dedicated Neon PostgreSQL project. All ticket decisions are enforced by the server.
create extension if not exists pgcrypto;
create table if not exists app_users (id uuid primary key default gen_random_uuid(), email text not null unique, password_hash text not null, full_name text not null, role text not null default 'guest' check (role in ('guest','organiser','platform_admin')), created_at timestamptz not null default now());
create table if not exists events (id uuid primary key default gen_random_uuid(), organiser_id uuid not null references app_users(id), title text not null, slug text not null unique, venue text not null, starts_at timestamptz not null, ends_at timestamptz, price_ngn integer not null check (price_ngn >= 0), capacity integer not null check (capacity > 0), status text not null default 'draft' check (status in ('draft','published','cancelled')), created_at timestamptz not null default now());
create table if not exists gate_assignments (event_id uuid not null references events(id) on delete cascade, user_id uuid not null references app_users(id) on delete cascade, gate_label text not null default 'Main gate', primary key(event_id,user_id));
create table if not exists ticket_orders (id uuid primary key default gen_random_uuid(), event_id uuid not null references events(id), buyer_id uuid not null references app_users(id), quantity integer not null check (quantity between 1 and 10), amount_ngn integer not null check (amount_ngn >= 0), payment_reference text not null, status text not null default 'pending' check (status in ('pending','approved','rejected')), reviewed_by uuid references app_users(id), reviewed_at timestamptz, created_at timestamptz not null default now());
create table if not exists tickets (id uuid primary key default gen_random_uuid(), event_id uuid not null references events(id), order_id uuid not null references ticket_orders(id), owner_id uuid not null references app_users(id), status text not null default 'issued' check (status in ('issued','revoked')), redeemed_at timestamptz, redeemed_by uuid references app_users(id), created_at timestamptz not null default now());
create table if not exists entry_scans (id bigint generated always as identity primary key, event_id uuid references events(id), ticket_id uuid references tickets(id), scanner_id uuid references app_users(id), outcome text not null check (outcome in ('approved','duplicate','invalid','revoked','wrong_event')), gate_label text, scanned_at timestamptz not null default now());
create index if not exists idx_ticket_orders_event_status on ticket_orders(event_id,status);
create index if not exists idx_tickets_event_status on tickets(event_id,status);
create index if not exists idx_tickets_owner on tickets(owner_id);
create index if not exists idx_scans_event_time on entry_scans(event_id,scanned_at desc);
